【4｜config.toml 内联写法（等价于上面 hooks.json）】
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ~/.codex/config.toml
[[hooks.Stop]]
[[hooks.Stop.hooks]]
type = "command"
command = "bash ~/.codex/hooks/run-tests-or-block.sh"
statusMessage = "跑测试，失败则不许交回"
timeout = 300

[[hooks.PreToolUse]]
matcher = "Bash"
[[hooks.PreToolUse.hooks]]
type = "command"
command = "python3 ~/.codex/hooks/guard-dangerous.py"
timeout = 10

